using System.Collections.Generic;
using Astrea.RunModifiers;
using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(menuName = "Data/Battle/Dice System/Player Dice Inventory Data")]
public class PlayerDiceInventoryData : ScriptableObject
{
	[Header("NameID")]
	[SerializeField]
	private string poolNameID;

	[Header("Character")]
	[SerializeField]
	private bool enableCurrentCharacter;

	[Header("Runtime Inventory Items")]
	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	protected List<InventoryItem> inventoryItems = new List<InventoryItem>();

	[Header("Events")]
	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	private StringEvent OnDicePoolChange;

	[SerializeField]
	private StringEvent OnDicePoolChangeNoShake;

	public string PoolNameID => poolNameID;

	private Character currentCharacter => ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter;

	private List<InventoryItem> DefaultInventoryItems
	{
		get
		{
			if (!enableCurrentCharacter)
			{
				return new List<InventoryItem>();
			}
			return currentCharacter.CharacterDice.DefaultInventoryItems;
		}
	}

	public List<InventoryItem> InventoryItems => inventoryItems;

	public StringEvent _OnDicePoolChange
	{
		set
		{
			OnDicePoolChange = value;
		}
	}

	public StringEvent _OnDicePoolChangeNoShake
	{
		set
		{
			OnDicePoolChangeNoShake = value;
		}
	}

	[Button(null)]
	public void OnResetToStartRunState(bool dailyRun = false)
	{
		inventoryItems.Clear();
		if (enableCurrentCharacter)
		{
			LoadInventory(dailyRun);
		}
		UpdateDicePoolText();
	}

	private void LoadInventory(bool dailyRun)
	{
		if (dailyRun)
		{
			LoadDefaultInventory();
			return;
		}
		SaveSystem.ModStarterDiceSetSave modStarterDiceSetSave = default(SaveSystem.ModStarterDiceSetSave);
		CharacterDice.ModStarterDiceSetsInfo modStarterDiceSetsInfo = null;
		if (ReferenceSingleton<AssetsReference>.Instance.SaveSystem.HasModStarterDiceSetBattleSaveKey(currentCharacter.CharacterName))
		{
			modStarterDiceSetSave = ReferenceSingleton<AssetsReference>.Instance.SaveSystem.LoadModStarterDiceSetBattle(currentCharacter.CharacterName);
			modStarterDiceSetsInfo = currentCharacter.CharacterDice.CustomInventoryItemsList.Find((CharacterDice.ModStarterDiceSetsInfo _) => _.PublishedId == modStarterDiceSetSave.PublishedId);
		}
		if (modStarterDiceSetsInfo == null)
		{
			LoadDefaultInventory();
			return;
		}
		CharacterDice.StarterDiceSetInfo starterDiceSetInfo = modStarterDiceSetsInfo.StarterDiceSetInfosList.Find((CharacterDice.StarterDiceSetInfo _) => _.SetId == modStarterDiceSetSave.SetId);
		if (starterDiceSetInfo == null)
		{
			LoadDefaultInventory();
			return;
		}
		List<InventoryItem> inventoryItemList = starterDiceSetInfo.inventoryItemList;
		for (int i = 0; i < inventoryItemList.Count; i++)
		{
			if (inventoryItemList[i].dice != null)
			{
				inventoryItems.Add(new InventoryItem(inventoryItemList[i].dice, inventoryItemList[i].amount));
			}
		}
	}

	private void LoadDefaultInventory()
	{
		for (int i = 0; i < DefaultInventoryItems.Count; i++)
		{
			inventoryItems.Add(new InventoryItem(DefaultInventoryItems[i].dice, DefaultInventoryItems[i].amount));
		}
	}

	public void OnReset()
	{
		UpdateDicePoolText();
	}

	public void RemoveAllStatusDice()
	{
		for (int num = inventoryItems.Count - 1; num >= 0; num--)
		{
			if (inventoryItems[num].dice.DiceTier == ReferenceSingleton<AssetsReference>.Instance.HexDieTier)
			{
				inventoryItems.Remove(inventoryItems[num]);
			}
		}
		UpdateDicePoolText();
	}

	public void RemoveAllButDice(Dice dice)
	{
		for (int num = inventoryItems.Count - 1; num >= 0; num--)
		{
			if (inventoryItems[num].dice != dice)
			{
				inventoryItems.Remove(inventoryItems[num]);
			}
		}
		UpdateDicePoolText();
	}

	public void RemoveAllJustPlayedDice()
	{
		for (int num = inventoryItems.Count - 1; num >= 0; num--)
		{
			if ((inventoryItems[num].dice as PlayerDice).DiceJustPlayed)
			{
				inventoryItems.Remove(inventoryItems[num]);
			}
		}
		UpdateDicePoolText();
	}

	public void RemoveAfterBattleDice()
	{
		for (int num = inventoryItems.Count - 1; num >= 0; num--)
		{
			if (inventoryItems[num].dice.RemoveAfterBattle)
			{
				inventoryItems.Remove(inventoryItems[num]);
			}
		}
	}

	public void UpdateDicePoolText()
	{
		if ((bool)OnDicePoolChange)
		{
			OnDicePoolChange.Raise(GetDicesAmount().ToString());
		}
	}

	public bool HasDice(Dice dice)
	{
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			if (inventoryItems[i].dice == dice)
			{
				return true;
			}
		}
		return false;
	}

	public List<Dice> GetAllDices()
	{
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			for (int j = 0; j < inventoryItems[i].amount; j++)
			{
				list.Add(inventoryItems[i].dice);
			}
		}
		return list;
	}

	public List<InventoryItem> GetAllInventoryItemsButJustPlayed()
	{
		List<InventoryItem> list = new List<InventoryItem>();
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			if (!(inventoryItems[i].dice as PlayerDice).DiceJustPlayed)
			{
				list.Add(inventoryItems[i]);
			}
		}
		return list;
	}

	public List<Dice> GetAllDiceFromSpecificTier(DiceTier diceTier, bool usedForDraw = true)
	{
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			InventoryItem inventoryItem = inventoryItems[i];
			for (int j = 0; j < inventoryItem.amount; j++)
			{
				if (inventoryItem.dice.DiceTier == diceTier)
				{
					list.Add(inventoryItem.dice);
				}
			}
		}
		if (usedForDraw && ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance is DiceInstance)
		{
			DiceInstance diceInstance = ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance as DiceInstance;
			if (diceInstance.OriginalDice is PlayerDice && (diceInstance.OriginalDice as PlayerDice).DiceJustPlayed)
			{
				list.Remove(diceInstance.OriginalDice);
			}
		}
		return list;
	}

	public List<Dice> GetAllDiceExceptSpecificTier(DiceTier diceTier, bool usedForDraw = true)
	{
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			InventoryItem inventoryItem = inventoryItems[i];
			for (int j = 0; j < inventoryItem.amount; j++)
			{
				if (inventoryItem.dice.DiceTier != diceTier)
				{
					list.Add(inventoryItem.dice);
				}
			}
		}
		if (usedForDraw && ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance is DiceInstance)
		{
			DiceInstance diceInstance = ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance as DiceInstance;
			if (diceInstance.OriginalDice is PlayerDice && (diceInstance.OriginalDice as PlayerDice).DiceJustPlayed)
			{
				list.Remove(diceInstance.OriginalDice);
			}
		}
		return list;
	}

	public List<InventoryItem> GetAllInventoryItemDiceFromSpecificTier(DiceTier diceTier)
	{
		List<InventoryItem> list = new List<InventoryItem>();
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			InventoryItem inventoryItem = inventoryItems[i];
			if (inventoryItem.dice.DiceTier == diceTier)
			{
				list.Add(new InventoryItem(inventoryItem.dice, inventoryItem.amount));
			}
		}
		return list;
	}

	public int GetDiceAmountFromSpecificTier(DiceTier diceTier)
	{
		int num = 0;
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			InventoryItem inventoryItem = inventoryItems[i];
			if (inventoryItem.dice.DiceTier == diceTier)
			{
				num += inventoryItem.amount;
			}
		}
		return num;
	}

	public int GetDiceAmountExceptSpecificTier(DiceTier diceTier)
	{
		int num = 0;
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			InventoryItem inventoryItem = inventoryItems[i];
			if (inventoryItem.dice.DiceTier != diceTier)
			{
				num += inventoryItem.amount;
			}
		}
		return num;
	}

	public List<Dice> GetSpecificDice(string diceName)
	{
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			InventoryItem inventoryItem = inventoryItems[i];
			for (int j = 0; j < inventoryItem.amount; j++)
			{
				if (inventoryItem.dice.DiceName.ToLower() == diceName.ToLower())
				{
					list.Add(inventoryItem.dice);
				}
			}
		}
		return list;
	}

	public List<Dice> GetSpecificDiceType(string diceName)
	{
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			InventoryItem inventoryItem = inventoryItems[i];
			for (int j = 0; j < inventoryItem.amount; j++)
			{
				if (inventoryItem.dice.DiceName.ToLower().Contains(diceName.ToLower()))
				{
					list.Add(inventoryItem.dice);
				}
			}
		}
		return list;
	}

	public int GetSpecificDiceAmount(string diceName)
	{
		int num = 0;
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			InventoryItem inventoryItem = inventoryItems[i];
			if (inventoryItem.dice.DiceName.ToLower() == diceName.ToLower())
			{
				num += inventoryItem.amount;
			}
		}
		return num;
	}

	public List<Dice> GetAllMagnetizedDice()
	{
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			InventoryItem inventoryItem = inventoryItems[i];
			for (int j = 0; j < inventoryItem.amount; j++)
			{
				if ((inventoryItem.dice as PlayerDice).Magnetized)
				{
					list.Add(inventoryItem.dice);
				}
			}
		}
		return list;
	}

	public void ResetAllMagnetizedDice()
	{
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			InventoryItem inventoryItem = inventoryItems[i];
			for (int j = 0; j < inventoryItem.amount; j++)
			{
				(inventoryItem.dice as PlayerDice).Magnetized = false;
			}
		}
	}

	public void ResetAllDiceJustPlayed()
	{
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			if (inventoryItems[i].dice is PlayerDice)
			{
				(inventoryItems[i].dice as PlayerDice).DiceJustPlayed = false;
			}
		}
	}

	public void ClearAllDices(bool ignoreJustPlayedDice = false)
	{
		if (ignoreJustPlayedDice)
		{
			for (int num = inventoryItems.Count - 1; num >= 0; num--)
			{
				if (!(inventoryItems[num].dice as PlayerDice).DiceJustPlayed)
				{
					inventoryItems.Remove(inventoryItems[num]);
				}
			}
		}
		else
		{
			inventoryItems.Clear();
		}
		if ((bool)OnDicePoolChange)
		{
			OnDicePoolChange.Raise(0.ToString());
		}
	}

	public int GetDicesAmount()
	{
		int num = 0;
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			num += inventoryItems[i].amount;
		}
		return num;
	}

	public int GetDicesAmountWithoutDiceJustPlayed()
	{
		int num = 0;
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			if (!(inventoryItems[i].dice as PlayerDice).DiceJustPlayed)
			{
				num += inventoryItems[i].amount;
			}
		}
		return num;
	}

	public int GetDiceAmount(Dice dice)
	{
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			if (dice == inventoryItems[i].dice)
			{
				return inventoryItems[i].amount;
			}
		}
		return -1;
	}

	public List<DiceTier> GetDifferentDiceTierList()
	{
		List<DiceTier> list = new List<DiceTier>();
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			InventoryItem inventoryItem = inventoryItems[i];
			list.AddIfNotAlreadyOnList(inventoryItem.dice.DiceTier);
		}
		return list;
	}

	public void IncreaseDiceAmount(Dice dice, int amount, bool insertAsFirst = false, bool updateDicePoolText = true, bool triggerOnDieAddedToDicePoolEvents = false, Vector2 stellarParadoxSpawnPosition = default(Vector2), bool dontTriggerStellarParadox = false)
	{
		for (int i = 0; i < amount; i++)
		{
			bool flag = false;
			for (int j = 0; j < inventoryItems.Count; j++)
			{
				if (dice == inventoryItems[j].dice)
				{
					UpdateDiceAmount(j, 1, updateDicePoolText);
					flag = true;
				}
			}
			if (!flag)
			{
				InventoryItem item = new InventoryItem(dice, 1);
				if (insertAsFirst)
				{
					inventoryItems.Insert(0, item);
				}
				else
				{
					inventoryItems.Add(item);
				}
				if ((bool)OnDicePoolChange && updateDicePoolText)
				{
					OnDicePoolChange.Raise(GetDicesAmount().ToString());
				}
			}
			if (triggerOnDieAddedToDicePoolEvents)
			{
				ReferenceSingleton<MiscOmensHandler>.Instance.MysticalMagnetOmenData?.Invoke(dice);
				ReferenceSingleton<MiscOmensHandler>.Instance.WealthBoxOmenAction?.Invoke();
				if (!dontTriggerStellarParadox)
				{
					ReferenceSingleton<RunModifiersManager>.Instance.CheckStellarParadoxRunModifierGainAdditionalDiceOnDiceRewardInstance(stellarParadoxSpawnPosition, dice, this);
				}
			}
		}
	}

	public void DecreaseDiceAmount(Dice dice, int amount, bool updateDicePoolText = true)
	{
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			if (inventoryItems[i].dice == dice)
			{
				UpdateDiceAmount(i, -amount, updateDicePoolText);
				if (GetDiceAmount(dice) == 0)
				{
					inventoryItems.Remove(inventoryItems[i]);
				}
				break;
			}
		}
	}

	public void DiceForged(DiceInstance diceInstance, Dice newOriginalDice)
	{
		if (diceInstance.Dice.DiceTier != ReferenceSingleton<AssetsReference>.Instance.HexDieTier && !diceInstance.Dice.RemoveAfterBattle)
		{
			for (int i = 0; i < diceInstance.OriginalDice.GetDiceFaces().Length; i++)
			{
				_ = newOriginalDice.GetDiceFaces()[i];
				DiceFace diceFace = diceInstance.OriginalDice.GetDiceFaces()[i];
				if (!diceFace.KeepChanges)
				{
					if (diceFace.EnableSecondAction)
					{
						new DiceFace(diceFace.FaceName, diceFace.ActionValue, diceFace.BattleAction, diceFace.SecondActionValue, diceFace.SecondBattleAction);
					}
					else
					{
						new DiceFace(diceFace.FaceName, diceFace.ActionValue, diceFace.BattleAction);
					}
				}
			}
			DecreaseDiceAmount(diceInstance.OriginalDice, 1);
			IncreaseDiceAmount(newOriginalDice, 1, insertAsFirst: true);
		}
		if (diceInstance.Dice.RemoveAfterBattle)
		{
			newOriginalDice.RemoveAfterBattle = true;
		}
		diceInstance.SetOriginalDice(newOriginalDice);
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.DiceFacesForgedAmount++;
	}

	private void UpdateDiceAmount(int i, int amount, bool updateDicePoolText = true)
	{
		inventoryItems[i].amount += amount;
		if ((bool)OnDicePoolChange && updateDicePoolText)
		{
			OnDicePoolChange.Raise(GetDicesAmount().ToString());
		}
	}

	public void SetInventoryItems(List<InventoryItem> inventoryItems)
	{
		this.inventoryItems.Clear();
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			this.inventoryItems.Add(new InventoryItem(inventoryItems[i].dice, inventoryItems[i].amount));
		}
		if ((bool)OnDicePoolChangeNoShake)
		{
			OnDicePoolChangeNoShake.Raise(GetDicesAmount().ToString());
		}
	}

	public bool IsAllStarterDieForgedAllDieFaces()
	{
		for (int i = 0; i < inventoryItems.Count; i++)
		{
			Dice dice = inventoryItems[i].dice;
			if (!(dice.DiceTier == ReferenceSingleton<AssetsReference>.Instance.StarterDieTier))
			{
				continue;
			}
			for (int j = 0; j < dice.DiceFaces.Length; j++)
			{
				if (!dice.DiceFaces[j].KeepChanges)
				{
					return false;
				}
			}
		}
		return true;
	}

